const REQ_PER_SEC = 1000;
const SPANS_PER_REQ = 10;
const SECONDS_PER_DAY = 86400;
const BYTES_PER_SPAN = 2048;
const RATE = 0.10; // head-based sampling rate; try 0.01

const rawSpans = REQ_PER_SEC * SPANS_PER_REQ * SECONDS_PER_DAY;
const keptSpans = Math.round(rawSpans * RATE);
const keptGB = (keptSpans * BYTES_PER_SPAN) / 1e9;

console.log('raw spans/day:', rawSpans);
console.log('kept spans/day at rate ' + RATE + ':', keptSpans);
console.log('kept GB/day:', keptGB.toFixed(1));
